    useMeta({ title: 'Tyres Report' });  
    
    const showMessage = inject('showMessage');
    const register_item_usage = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    // const enforceMax = inject('enforceMax')
    const tableShimmer = inject('tableShimmer');
    const waitIndicator = inject('waitIndicator')
    const loadingSpinner = inject('loadingSpinner'); 
   
    
    const loading_spinner = ref(false);
const tyresListColumns = ref(['sno','type','code','dimension','purchased_rate','status','condition','date','action']);
const tyreColumns = ref(['Sno','asset','jobcard', 'date_installed','date_removed','position','status']);
    const isEditing = ref(false);
    const register_item_usage_id = ref('');
    const direction = ref('')

const today = new Date().toISOString().split('T')[0];
const start_date = ref(today);
const end_date = ref(today);
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 51 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

const formatRate = inject('formatRate')
const tyresList = ref([])
const getTyres = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`tyres?type_id=${tyres_type.value.id || ''}`)
    tyresList.value = response.data.map((item, index) => ({
      ...item,
      sno: index + 1,
      purchased_rate : formatRate(item.rate),
      dimension :item.description,
      condition: item.condition === 'REMOVED' ? 'USED' : item.condition
    }))
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    loading_spinner.value = false
  }
}
    

const resetForm = () => {
   tyreForm.value = {
  id : '',
  type : '',
  code : '',
  dimension : '',
  rate : '',
  status : '',
  date : ''
}
};


 const openEditModal = async (row) => {
    isEditing.value = true;
    console.log(row);
    register_item_usage_id.value = row;

    if (!storeItems.value.length) {
        await getTyreTypes();
    }

 // Find the matching store item
    const matched = storeItems.value.find(si => si.id === row.type_id);
    
    // Populate tyreForm with the row data - THIS IS WHAT YOU'RE MISSING
    tyreForm.value = {
        id: row.id,
        type: matched || row.type || '',  // Use matched object or fallback
        code: row.code || '',
        dimension: row.dimension || row.description || '',
        rate: row.rate || '',
        status: row.status || '',
        date: row.date || ''
    };
};


const storeItems = ref([])
const getTyreTypes = async () => {
     loading_spinner.value = true
  try {
    const response = await axiosInstance.get(`tyre-groups`)
    storeItems.value = response.data
      .map((item, index) => ({
        ...item,
        SNo: index + 1,
      }))
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    loading_spinner.value = false
  }
}

const store_item = ref('')
const tyres_type = ref('')
const description = ref('')
const date = ref('')
const received = ref('')
const issued = ref('')
const loading = ref(false)

const tyreForm = ref({
  id : '',
  type : '',
  code : '',
  dimension : '',
  rate : '',
  status : '',
  date : ''
})

const saveTyres = async () => {
    loading.value = true;
    const payload = {
      type_id : tyreForm.value.type.id,
      code : tyreForm.value.code,
      dimension : tyreForm.value.dimension,
      rate : tyreForm.value.rate,
      status : tyreForm.value.status,
      date : tyreForm.value.date
    };


    try {
        if (tyreForm.value.id !== '') {
            await axiosInstance.put(`tyres/${tyreForm.value.id}`, payload);
            showMessage('Tyre Updated');
        } else {
            await axiosInstance.post('tyres', payload);
            showMessage('Tyre Registered');
        }
        document.getElementById('close_modal').click();
        getTyres();
        resetForm();
    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        loading.value = false;
    }
};

watch(start_date, () => {
    getTyres();
});


watch(tyres_type, () => {
    getTyres();
});




