      <th>Acquired_Date</th>
      <th class="text-right">Price</th>
    </tr>
  </thead>
  <tbody>
    ${tyresList.value.map((row, index) => `
    <tr>
      <td>${index + 1}</td>
      <td>${row.type || '--'}</td>
      <td class="text-right">${row.code || '--'}</td>
      <td>${row.dimension || '--'}</td>
      <td class="text-right">${row.status || '--'}</td>
       <td class="text-right">${row.condition || '--'}</td>
      <td>${row.date || '--'}</td>
      <td class="text-right">${formatRate(row.rate) || '--'}</td>
    </tr>
    `).join('')}
    <tr>
      <td colspan="6" class="text-right"><strong>TOTAL:</strong></td>
      <td class="text-right"><strong>QTY : ${totalQuantity}</strong></td>
      <td class="text-right"><strong>${formatRate(totalCost)}</strong></td>
    </tr>
  </tbody>
</table>

</body>
</html>
`;

    const iframeDoc = iframe.contentWindow.document;
    iframeDoc.open();
    iframeDoc.write(printContent);
    iframeDoc.close();

    iframe.onload = () => {
      iframe.contentWindow.focus();
      iframe.contentWindow.print();
      setTimeout(() => {
        document.body.removeChild(iframe);
      }, 1000);
    };
  } catch (error) {
    showError(`Failed to print report: ${error.message}`);
  }
};

const tyres = ref([]);
   const getTyreUsages= async(id) =>{
     loading.value = true
try{
    const response = await axiosInstance.get(`asset-assemblies?child_asset_id=${id}`)
    tyres.value = response.data.map((item,index)=>({
      ...item,
      Sno : index + 1,
       tyre_status: item.status,
       status : {
        name : item.status ==='INSTALLED' ? 'IN USE' : 'REMOVED',
        color : item.status ==='INSTALLED' ? 'success' : 'dark'
      },
      tyre_no : item.child_asset,
          date_installed : item.installed_at ?? '---',
      date_removed : item.removed_at ?? '---' ,
      jobcard : item.source_id,
      asset: item.parent_asset
}));
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
         loading.value = false
    }
}

